const translations={en:{buy:'Buy',memes:'Memes',community:'Community',tagline:'China’s iconic cigarette just came to life. Meet CHUNG.',contract:'CA coming soon. Follow X',scroll:'Enter the Chungverse',pause:'Pause motion',play:'Play motion',galleryLabel:"The community’s natural habitat",galleryTitle:'Certified Chung moments.',buyTitle:'Same grin.<br>New chain.',buyText:'CHUNG is finding its home on BNB Chain. The official contract will be announced on our X account, @chung_bnb.',launch:'Launch details coming soon',prepare:'Get ready for CHUNG',step1:'Set up your wallet',step1text:'Use a wallet that supports BNB Smart Chain.',step2:'Have BNB ready',step2text:'BNB is used for network fees and swaps.',step3:'Wait for the official contract',step3text:'Verify the address on our official X account before making any swap.',notLive:'Trading not live yet',communityLabel:'One grin. Two languages. All Chung.',communityTitle:'Make yourself<br>at home.',communityText:'The hills are greener with company. Official community links are on their way.',soon:'Coming soon',back:'Back to the hills ↑',footer:'An independent meme project. Not affiliated with the Chunghwa tobacco brand. Crypto assets carry risk.',download:'Download meme ↓'},zh:{buy:'购买',memes:'表情包',community:'社区',tagline:'熟悉的中华香烟，如今有了自己的个性。认识一下，CHUNG。',contract:'合约即将公布，关注 X',scroll:'进入 CHUNG 世界',pause:'暂停动画',play:'播放动画',galleryLabel:'这里是社区的快乐老家',galleryTitle:'每一刻，都很 CHUNG。',buyTitle:'熟悉的笑容。<br>全新的链。',buyText:'CHUNG 即将登陆 BNB Chain。官方合约地址将在 X 账号 @chung_bnb 公布。',launch:'上线信息即将公布',prepare:'准备好迎接 CHUNG',step1:'准备钱包',step1text:'使用支持 BNB Smart Chain 的钱包。',step2:'准备 BNB',step2text:'BNB 可用于支付网络手续费和兑换。',step3:'等待官方合约公布',step3text:'兑换前，请通过我们的官方 X 账号核实合约地址。',notLive:'交易尚未开放',communityLabel:'一种笑容，两种语言，都是 CHUNG。',communityTitle:'来这里，<br>就像回家。',communityText:'有朋友，青山更有趣。官方社区链接即将公布。',soon:'敬请期待',back:'回到青山 ↑',footer:'独立 Meme 项目，与中华香烟品牌无关联。加密资产存在风险。',download:'下载表情包 ↓'}};
let lang=localStorage.getItem('chung-language')==='zh'?'zh':'en';
const video=document.querySelector('#landscape'), motion=document.querySelector('#motion');
function render(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.querySelectorAll('[data-i]').forEach(e=>{e.innerHTML=translations[lang][e.dataset.i]||e.innerHTML});document.querySelector('#language').textContent=lang==='en'?'中文':'EN';document.querySelector('#language').setAttribute('aria-label',lang==='en'?'切换到中文':'Switch to English');motion.textContent=translations[lang][video.paused?'play':'pause']}
document.querySelector('#language').onclick=()=>{lang=lang==='en'?'zh':'en';localStorage.setItem('chung-language',lang);render()};
motion.onclick=()=>{if(video.paused)video.play().catch(()=>{});else video.pause()};
function motionState(){motion.textContent=translations[lang][video.paused?'play':'pause'];motion.setAttribute('aria-pressed',String(video.paused))}video.addEventListener('play',motionState);video.addEventListener('pause',motionState);
if(matchMedia('(prefers-reduced-motion: reduce)').matches){video.autoplay=false;video.pause()}
const dialog=document.querySelector('#lightbox');document.querySelectorAll('[data-meme]').forEach(b=>b.onclick=()=>{const src=b.querySelector('img').src;document.querySelector('#large-meme').src=src;document.querySelector('#large-meme').alt=b.querySelector('img').alt;document.querySelector('#download-meme').href=src;dialog.showModal()});document.querySelector('#close-dialog').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};
document.querySelector('#mascot').addEventListener('error',()=>{document.querySelector('#model-fallback').hidden=false;document.querySelector('#mascot').hidden=true});render();
